content.text:
{
  "name": "MiR100自主移动机器人",
  "name_en": "MiR100 autonomous mobile robot",
  "manufacturer": "Mobile Industrial Robots (MiR)",
  "description": "MiR100 是一款用于实验室、产线和仓储环境的自主移动机器人，可执行物料搬运、样品转运和内部物流配送任务。设备通常通过无线网络接入管理系统，以便进行任务调度、状态监控和系统集成。",
  "description_en": "The MiR100 is an autonomous mobile robot used in laboratories, production areas, and warehouses for material transport, sample transfer, and internal logistics. It typically connects over Wi-Fi to management systems for task scheduling, status monitoring, and system integration.",
  "tag_hints": [
    "autonomous mobile robot",
    "AMR",
    "material transport",
    "internal logistics",
    "Wi-Fi connectivity",
    "fleet management"
  ],
  "actions": [
    {
      "action_name": "auto-bssid",
      "description": "获取/设置当前无线网络接入点的 BSSID（MAC 地址）",
      "description_en": "Get/set the BSSID (MAC address) of the current Wi-Fi access point."
    },
    {
      "action_name": "auto-connected",
      "description": "获取/设置该无线连接是否已接入网络",
      "description_en": "Get/set whether this Wi-Fi connection is connected to the network."
    },
    {
      "action_name": "auto-device",
      "description": "获取/设置此无线连接使用的网络设备或适配器",
      "description_en": "Get/set the network device or adapter used for this Wi-Fi connection."
    },
    {
      "action_name": "auto-dns",
      "description": "获取/设置此无线连接的 DNS 服务器",
      "description_en": "Get/set the DNS servers for this Wi-Fi connection."
    },
    {
      "action_name": "auto-ip_address",
      "description": "获取/设置此无线连接的 IP 地址",
      "description_en": "Get/set the IP address for this Wi-Fi connection."
    },
    {
      "action_name": "auto-last_connected",
      "description": "获取/设置此无线连接上次成功连接的日期和时间",
      "description_en": "Get/set the date and time when this Wi-Fi connection was last successfully connected."
    },
    {
      "action_name": "auto-mac",
      "description": "获取/设置网络适配器的 MAC 地址",
      "description_en": "Get/set the MAC address of the network adapter."
    },
    {
      "action_name": "auto-name",
      "description": "获取/设置该连接的名称或标识",
      "description_en": "Get/set the name or identifier of the connection."
    },
    {
      "action_name": "auto-netmask",
      "description": "获取/设置此无线连接的子网掩码",
      "description_en": "Get/set the netmask for this Wi-Fi connection."
    },
    {
      "action_name": "auto-security",
      "description": "获取/设置该无线连接使用的安全方式",
      "description_en": "Get/set the security method used by this Wi-Fi connection."
    },
    {
      "action_name": "auto-type",
      "description": "获取/设置连接类型（如 802.11 无线）",
      "description_en": "Get/set the connection type, such as 802.11 wireless."
    },
    {
      "action_name": "auto-url",
      "description": "获取/设置该特定连接的 URL",
      "description_en": "Get/set the URL of this specific connection."
    },
    {
      "action_name": "auto-uuid",
      "description": "获取/设置该连接的 UUID",
      "description_en": "Get/set the UUID of the connection."
    },
    {
      "action_name": "auto-to_dict",
      "description": "将当前无线连接信息导出为字典",
      "description_en": "Export the current Wi-Fi connection information as a dictionary."
    },
    {
      "action_name": "auto-to_str",
      "description": "将当前无线连接信息导出为字符串",
      "description_en": "Export the current Wi-Fi connection information as a string."
    }
  ]
}

